css:
@import url("https://fonts.googleapis.com/css2?family=Prata&family=Heebo:wght@400;500;700&display=swap");
:root{--tl:#2F6F6A;--tl2:#245753;--gd:#C9A227;--sl:#2B3440;--mist:#EEF3F2;--gr:#5B6570;--ln:#DCE4E3;--h:"Prata",Georgia,serif;--b:"Heebo",system-ui,sans-serif}
*,*::before,*::after{box-sizing:border-box}[hidden]{display:none!important}html{scroll-behavior:smooth}body{margin:0;font-family:var(--b);font-size:17px;line-height:1.65;color:var(--sl);background:#fff}
img{max-width:100%;height:auto;display:block}a{color:inherit}h1,h2,h3{font-family:var(--h);font-weight:400;margin:0;line-height:1.12}
.wrap{max-width:1200px;margin:0 auto;padding:0 22px}.skip{position:absolute;left:-999px}.skip:focus{left:10px;top:10px;background:var(--gd);padding:8px;z-index:99}
:focus-visible{outline:3px solid var(--gd);outline-offset:2px}
.hero{position:relative;min-height:640px;color:#fff;display:flex;flex-direction:column;background:var(--sl)}
.hero>img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}.hero:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,rgba(20,26,32,.55),rgba(20,26,32,.15) 40%,rgba(20,26,32,.75))}
.nav{position:relative;z-index:5;display:flex;justify-content:space-between;align-items:center;height:84px}.logo{font-family:var(--h);font-size:26px;text-decoration:none;display:flex;gap:10px;align-items:center}
.menu{display:flex;gap:28px;list-style:none;margin:0;padding:0;font-weight:500}.menu a{text-decoration:none}.menu a:hover{color:var(--gd)}
.burger{display:none;background:none;border:2px solid #fff;color:#fff;width:44px;height:40px;border-radius:8px;font-size:20px;cursor:pointer}
.hc{position:relative;z-index:3;margin-top:auto;padding-bottom:40px}.hero h1{font-size:clamp(42px,5.6vw,76px);max-width:13em}.hero p{font-size:19px;max-width:32em;margin:16px 0 26px;color:#E7ECEF}
.sbox{background:#fff;color:var(--sl);border-radius:14px;padding:16px;display:grid;grid-template-columns:auto 1.2fr 1fr 1fr auto;gap:12px;align-items:end;box-shadow:0 20px 40px rgba(0,0,0,.2)}
.sbox label{display:block;font-size:13px;font-weight:700;color:var(--gr);margin-bottom:4px}.sbox select{width:100%;font:16px var(--b);padding:11px;border:1px solid var(--ln);border-radius:8px;background:#fff;color:var(--sl)}
.tog{display:flex;background:var(--mist);border-radius:10px;padding:4px}.tog button{font:700 15px var(--b);border:0;background:transparent;padding:10px 16px;border-radius:8px;cursor:pointer;color:var(--sl)}.tog button[aria-pressed=true]{background:var(--tl);color:#fff}
.btn{display:inline-block;background:var(--tl);color:#fff;text-decoration:none;font:700 16px var(--b);padding:13px 22px;border-radius:8px;border:0;cursor:pointer}.btn.g{background:var(--gd);color:var(--sl)}
section{padding:84px 0}.sh{display:flex;justify-content:space-between;align-items:flex-end;flex-wrap:wrap;gap:12px;margin-bottom:26px}.sh h2{font-size:clamp(32px,4vw,48px)}.sh p{color:var(--gr);margin:6px 0 0}
.fv{font:600 15px var(--b);background:none;border:1px solid var(--ln);border-radius:30px;padding:8px 14px;cursor:pointer;color:var(--sl)}.fv[aria-pressed=true]{background:var(--sl);color:#fff}
.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}
.pc{border-radius:14px;overflow:hidden;background:#fff;border:1px solid var(--ln);display:flex;flex-direction:column}
.pi{position:relative}.pi img{width:100%;aspect-ratio:4/3;object-fit:cover}.pi .st{position:absolute;left:12px;top:12px;background:#fff;border-radius:6px;padding:3px 10px;font-size:13px;font-weight:700}.pi .st.r{background:var(--gd)}
.hrt{position:absolute;right:12px;top:12px;width:40px;height:40px;border-radius:50%;border:0;background:#fff;cursor:pointer;display:grid;place-items:center}.hrt[aria-pressed=true] path{fill:#D64545;stroke:#D64545}
.pc .c{padding:16px 18px 18px}.pc .pr{font-family:var(--h);font-size:26px;color:var(--tl2)}.pc h3{font-family:var(--b);font-weight:500;font-size:17px;margin:4px 0 10px}.pc .ad{color:var(--gr);font-size:15px}
.ft{display:flex;gap:16px;border-top:1px solid var(--ln);padding-top:12px;margin-top:12px;font-size:15px;color:var(--gr)}.ft b{color:var(--sl)}
.none{grid-column:1/-1;background:var(--mist);padding:30px;border-radius:14px;text-align:center}
.mort{background:var(--mist)}.mg{display:grid;grid-template-columns:1fr 1fr;gap:40px;align-items:start}.mg>div{min-width:0}
.mf{background:#fff;border-radius:14px;padding:26px}.row2{display:grid;grid-template-columns:1fr 1fr;gap:14px}.row2>div{min-width:0}
.mf label{display:block;font-weight:700;font-size:15px;margin-bottom:6px}.mf input{width:100%;font:17px var(--b);padding:11px;border:1px solid var(--ln);border-radius:8px;margin-bottom:14px;color:var(--sl)}
.mf input[type=range]{padding:0;border:0;accent-color:var(--tl)}.rv{float:right;font-weight:700;color:var(--tl2)}
.mres{background:var(--sl);color:#fff;border-radius:14px;padding:28px}.mres small{color:#B9C2CB}.mres .big{font-family:var(--h);font-size:56px;line-height:1.05;margin:6px 0 18px;color:var(--gd)}
.split{display:flex;height:16px;border-radius:8px;overflow:hidden;margin:6px 0 10px}.split i:first-child{background:var(--gd)}.split i:last-child{background:#6F8FA0}
.lg{display:flex;gap:18px;font-size:14px;color:#D4DAE0;flex-wrap:wrap}.lg span:before{content:"";display:inline-block;width:10px;height:10px;border-radius:2px;margin-right:6px;background:var(--gd)}.lg span+span:before{background:#6F8FA0}
.mres dl{display:grid;grid-template-columns:1fr auto;gap:8px;margin:18px 0 0;font-size:15px}.mres dd{margin:0;font-weight:700;text-align:right}
.agents .ag{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:20px}.agents img{width:100%;aspect-ratio:1/1;object-fit:cover;border-radius:14px}.agents h3{font-size:22px;margin-top:12px}.agents p{margin:2px 0 0;color:var(--gr);font-size:15px}
.cta{background:var(--tl);color:#fff}.cta .wrap{display:flex;justify-content:space-between;align-items:center;gap:20px;flex-wrap:wrap}.cta h2{font-size:clamp(28px,3.6vw,42px);max-width:18em}
footer{background:var(--sl);color:#B9C2CB;padding:30px 0;font-size:15px}footer .wrap{display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px}
@media (max-width:980px){.sbox{grid-template-columns:1fr 1fr}.sbox .tog{grid-column:1/-1}.sbox .btn{grid-column:1/-1}.grid{grid-template-columns:1fr 1fr}.mg{grid-template-columns:1fr}.agents .ag{grid-template-columns:1fr 1fr}}
@media (max-width:760px){.burger{display:block}.menu{display:none;position:absolute;top:84px;left:0;right:0;background:var(--sl);flex-direction:column;padding:18px 22px;z-index:30}.menu.open{display:flex}.grid{grid-template-columns:1fr}.sbox,.row2{grid-template-columns:1fr}.hero{min-height:720px}}
@media (prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}

javascript:
(()=>{const $=id=>document.getElementById(id);const U=i=>`https://images.unsplash.com/photo-${i}?w=700&q=75&auto=format&fit=crop`;
const H=[["buy",689000,"Scottsdale","8421 E Desert Cove Ave",4,3,2650,"1600596542815-ffad4c1539a9","White modern house with a pool"],["buy",1250000,"Scottsdale","10240 N Palo Verde Dr",5,4,3900,"1613490493576-7fde63acd811","Large modern villa with a long pool"],["buy",512000,"Tempe","1734 S Mill Ave",3,2,1850,"1570129477492-45c003edd2be","White two-storey house with a porch and lawn"],["buy",398000,"Phoenix","4410 N 24th St",3,2,1520,"1564013799919-ab600027ffc6","White house with palm trees and a pool"],["buy",845000,"Chandler","2906 W Ocotillo Rd",4,3,3100,"1580587771525-78b9dba3b914","Modern house with an infinity pool"],["buy",459000,"Phoenix","3125 E Indian School Rd",2,2,1380,"1512917774080-9991f1c4c750","Glass-fronted home beside a pool"],["rent",2850,"Tempe","640 W Broadway Rd",3,2,1600,"1570129477492-45c003edd2be","White family house with a porch"],["rent",3900,"Scottsdale","7020 E 1st Ave",4,3,2400,"1580587771525-78b9dba3b914","Modern house with pool"],["rent",1950,"Phoenix","1818 N Central Ave",2,1,980,"1564013799919-ab600027ffc6","House with palm trees"]];
let mode='buy';const fav=new Set();let favOnly=false;const f=n=>'$'+Math.round(n).toLocaleString('en-US');
function maxOpts(){$('mx').innerHTML=(mode==='buy'?[0,400000,500000,700000,1000000]:[0,2000,3000,4000]).map(v=>`<option value="${v}">${v?'Up to '+f(v)+(mode==='rent'?' a month':''):'No max'}</option>`).join('')}
function draw(){const loc=$('loc').value,bd=+$('bd').value,mx=+$('mx').value;let r=H.map((h,i)=>[h,i]).filter(([h])=>h[0]===mode&&(!loc||h[2]===loc)&&h[4]>=bd&&(!mx||h[1]<=mx));if(favOnly)r=r.filter(([h,i])=>fav.has(i));
$('l1').textContent=mode==='buy'?'Homes for sale':'Homes to rent';$('cnt').textContent=`${r.length} home${r.length===1?'':'s'} match your search`;$('fvo').textContent=`♥ Saved only (${fav.size})`;
$('grid').innerHTML=r.length?r.map(([h,i])=>`<article class="pc"><div class="pi"><img src="${U(h[7])}" alt="${h[8]}" width="700" height="525" loading="lazy"><span class="st ${h[0]==='rent'?'r':''}">${h[0]==='rent'?'For rent':'For sale'}</span><button type="button" class="hrt" data-i="${i}" aria-pressed="${fav.has(i)}" aria-label="Save ${h[3]}"><svg width="20" height="20" viewBox="0 0 24 24" aria-hidden="true"><path d="M12 21s-8-5-8-11a4.5 4.5 0 0 1 8-3 4.5 4.5 0 0 1 8 3c0 6-8 11-8 11z" fill="none" stroke="#2B3440" stroke-width="2"/></svg></button></div><div class="c"><div class="pr">${f(h[1])}${h[0]==='rent'?'<small style="font-size:15px"> a month</small>':''}</div><h3>${h[3]}</h3><div class="ad">${h[2]}, AZ</div><div class="ft"><span><b>${h[4]}</b> beds</span><span><b>${h[5]}</b> baths</span><span><b>${h[6].toLocaleString('en-US')}</b> sq ft</span></div></div></article>`).join(''):'<p class="none">No homes match. Try a bigger budget or any area.</p>'}
document.querySelector('.tog').onclick=e=>{const b=e.target.closest('button');if(!b)return;document.querySelectorAll('.tog button').forEach(x=>x.setAttribute('aria-pressed',x===b));mode=b.dataset.m;maxOpts();draw()};
$('sf').addEventListener('change',draw);$('sf').onsubmit=e=>{e.preventDefault();draw();$('homes').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})};
$('grid').onclick=e=>{const b=e.target.closest('.hrt');if(!b)return;const i=+b.dataset.i;fav.has(i)?fav.delete(i):fav.add(i);draw()};
$('fvo').onclick=()=>{favOnly=!favOnly;$('fvo').setAttribute('aria-pressed',favOnly);draw()};maxOpts();draw();
function mort(){const p=+$('mp').value||0,d=+$('md').value,r=(+$('mr').value||0)/1200,n=(+$('mt').value||30)*12;const loan=p*(1-d/100);const pay=r?loan*r/(1-Math.pow(1+r,-n)):loan/n;const tax=p*.011/12;
$('mdv').textContent=d+'%';$('mo').textContent=f(pay+tax);$('la').textContent=f(loan);$('dp').textContent=f(p*d/100);$('ti').textContent=f(pay*n-loan);$('spa').style.width=pay/(pay+tax)*100+'%';$('spb').style.width=tax/(pay+tax)*100+'%'}
$('mf').addEventListener('input',mort);$('mf').onsubmit=e=>e.preventDefault();mort();
})();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
